//! Coordinate grids, checked against the C library.
//!
//! `plot_grid_values_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/plot_grid_values_probe.c`, which reads, through
//! C's string getter, the values a grid chooses for the attributes with
//! dynamic defaults (`Gap(1)`, `Edge(2)`, `Labelling` and the rest) on the
//! grid test Plots of `fixtures/plot/cases.txt`, built as C's `testgrid.c`
//! builds them, and on variants; and the call log of one invisible grid.
//! `grid_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/capture_grid_logs.sh`, which runs the reference
//! build's `testgrid` over the same cases and records the call log of each
//! grid, and of the grid with its numerical and textual labels and title
//! turned off. The labels of each grid are also compared with the reference
//! SVGs in `fixtures/plot/expected`, as C's own `run_grid_test.cmake` does.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[allow(dead_code)]
#[path = "plot_grid_values_oracle/cases.rs"]
mod values;

#[rustfmt::skip]
#[path = "grid_oracle/cases.rs"]
mod logs;

use starlink_ast::error::ErrorCode;
use starlink_ast::frames::{BasicFrameBuilder, FrameRef};
use starlink_ast::grf::{LogGrf, SvgGrf, SvgOptions};
use starlink_ast::mappings::PermMap;
use starlink_ast::plot::{Draw, Edge, Labelling, Plot, UsedValues};

use crate::common::plot::{FailingGrf, apply_settings, grid_cases, testgrid_plot};

/// The Plot of a grid values case: a grid test case or a variant.
fn values_plot(name: &str) -> Plot {
    let cases = grid_cases();
    if let Some(case) = cases.iter().find(|c| c.name == name) {
        return testgrid_plot(case);
    }
    let &(_, base, extra, pbox) = values::VARIANTS.iter().find(|v| v.0 == name).unwrap();
    let mut plot = match base {
        Some(base) => {
            let mut case = cases.into_iter().find(|c| c.name == base).unwrap();
            if pbox.is_some() {
                case.pbox = pbox;
            }
            testgrid_plot(&case)
        }
        None => {
            let pbox = if extra.contains("LogPlot") {
                [1.0, 0.0, 1000.0, 10.0]
            } else {
                [0.0, 0.0, 10.0, 10.0]
            };
            let frame = BasicFrameBuilder::new(2).build().unwrap();
            Plot::new(&frame, [0.1, 0.1, 0.9, 0.9], pbox).unwrap()
        }
    };
    apply_settings(&mut plot, extra).unwrap();
    plot
}

/// A used value as C's string getter prints it.
fn printed(used: &UsedValues, name: &str) -> String {
    let (attr, axis) = match name.split_once('(') {
        Some((a, rest)) => (a, rest.trim_end_matches(')').parse::<usize>().unwrap() - 1),
        None => (name, 0),
    };
    let num = |v: f64| format!("{v:?}");
    let flag = |b: bool| if b { "1" } else { "0" }.to_string();
    match attr {
        "Gap" => num(used.gap[axis]),
        "LogGap" => num(used.log_gap[axis]),
        "Centre" => num(used.centre[axis]),
        "Edge" => match used.edge[axis] {
            Edge::Left => "left",
            Edge::Top => "top",
            Edge::Right => "right",
            Edge::Bottom => "bottom",
        }
        .to_string(),
        "LabelAt" => num(used.label_at[axis]),
        "LabelUnits" => flag(used.label_units[axis]),
        "LogTicks" => flag(used.log_ticks[axis]),
        "LogLabel" => flag(used.log_label[axis]),
        "MinTick" => used.min_tick[axis].to_string(),
        "TextLab" => flag(used.text_lab[axis]),
        "MajTickLen" => num(used.maj_tick_len[axis]),
        "Grid" => flag(used.grid),
        "Labelling" => match used.labelling {
            Labelling::Exterior => "exterior",
            Labelling::Interior => "interior",
        }
        .to_string(),
        "Border" => flag(used.border),
        other => panic!("no used value {other}"),
    }
}

/// Whether a value printed by Rust and one printed by C are the same value.
fn same(got: &str, want: &str) -> bool {
    match (got.parse::<f64>(), want.parse::<f64>()) {
        (Ok(g), Ok(w)) => g == w,
        _ => got == want,
    }
}

#[test]
fn used_values_match_the_c_library() {
    let mut failures = Vec::new();
    for case in values::CASES {
        let mut plot = values_plot(case.name);
        let mut grf = LogGrf::new(Vec::new());
        let used = match plot.used_values(&mut grf) {
            Ok(u) => u,
            Err(e) => {
                failures.push(format!("{}: {e}", case.name));
                continue;
            }
        };
        let log = String::from_utf8(grf.finish().unwrap()).unwrap();
        for (name, want) in values::NAMES.iter().zip(case.values) {
            let got = printed(&used, name);
            if !same(&got, want) {
                failures.push(format!("{}: {name} is {got}, C gives {want}", case.name));
            }
        }
        if log != case.log {
            failures.push(format!(
                "{}: the invisible grid's log differs from C's",
                case.name
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn grid_rejects_a_plot_that_is_not_two_dimensional() {
    let frame = BasicFrameBuilder::new(2).build().unwrap();
    let mut plot = Plot::new(&frame, [0.1, 0.1, 0.9, 0.9], [0.0, 0.0, 10.0, 10.0]).unwrap();
    let to_1d = PermMap::new(&[1, -1], &[1], &[0.0]).unwrap();
    plot.add_frame(
        FrameRef::Current,
        Box::new(to_1d),
        Box::new(BasicFrameBuilder::new(1).build().unwrap()),
    )
    .unwrap();
    let err = plot.used_values(&mut LogGrf::new(Vec::new())).unwrap_err();
    assert_eq!(err.code(), ErrorCode::Naxin);
}

/// Cases whose call log is not compared, each with the reason; a companion
/// test fails when one starts to match.
const GRID_LOG_EXCLUDED: &[(&str, &str)] = &[];

/// Cases whose labels are not compared with the reference SVG, as C's own
/// test leaves them out (`skip_text_compare` in cases.txt).
const GRID_LABELS_EXCLUDED: &[(&str, &str)] = &[(
    "cobe",
    "the degree symbol lands on a half-pixel boundary, so its rounded position in the \
     reference SVG depends on whether the C build fused multiply-adds",
)];

/// The call log of the grid of a cases.txt case, with `extra` attributes.
fn grid_log(name: &str, extra: &str) -> String {
    let case = grid_cases().into_iter().find(|c| c.name == name).unwrap();
    let mut plot = testgrid_plot(&case);
    apply_settings(&mut plot, extra).unwrap();
    let mut grf = LogGrf::new(Vec::new());
    plot.draw_grid(&mut grf).unwrap();
    String::from_utf8(grf.finish().unwrap()).unwrap()
}

/// The first line at which two logs differ.
fn first_difference(got: &str, want: &str) -> String {
    for (i, (g, w)) in got.lines().zip(want.lines()).enumerate() {
        if g != w {
            return format!("line {}: got {g:?}, C gives {w:?}", i + 1);
        }
    }
    format!(
        "{} lines, C gives {}",
        got.lines().count(),
        want.lines().count()
    )
}

/// Each case's log compared with C's, `lines` choosing the lines-only log.
fn compare_logs(lines: bool) -> Vec<String> {
    let mut failures = Vec::new();
    for &(name, full, lines_log) in logs::CASES {
        if GRID_LOG_EXCLUDED.iter().any(|e| e.0 == name) {
            continue;
        }
        let (extra, want) = if lines {
            ("NumLab=0,TextLab=0,DrawTitle=0", lines_log)
        } else {
            ("", full)
        };
        let got = grid_log(name, extra);
        if got != want {
            failures.push(format!("{name}: {}", first_difference(&got, want)));
        }
    }
    failures
}

#[test]
fn grid_lines_only_match_the_c_library() {
    let failures = compare_logs(true);
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn grid_logs_match_the_c_library() {
    let failures = compare_logs(false);
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn excluded_grid_logs_still_differ() {
    for &(name, reason) in GRID_LOG_EXCLUDED {
        let &(_, full, _) = logs::CASES.iter().find(|c| c.0 == name).unwrap();
        assert_ne!(
            grid_log(name, ""),
            full,
            "{name} now matches ({reason}); remove its exclusion"
        );
    }
}

/// The `<text` lines of an SVG, sorted, as `run_grid_test.cmake` compares
/// them.
fn text_lines(svg: &str) -> Vec<String> {
    let mut lines: Vec<String> = svg
        .lines()
        .filter(|l| l.starts_with("<text "))
        .map(str::to_string)
        .collect();
    lines.sort();
    lines
}

/// The `<text` lines of the port's SVG of a case and of C's reference.
fn labels_of(case: &crate::common::plot::GridCase) -> (Vec<String>, Vec<String>) {
    let mut plot = testgrid_plot(case);
    let mut svg = SvgGrf::new(Vec::new(), SvgOptions::default()).unwrap();
    plot.draw_grid(&mut svg).unwrap();
    let got = String::from_utf8(svg.finish().unwrap()).unwrap();
    let path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(&case.reference);
    let want = std::fs::read_to_string(path).unwrap();
    (text_lines(&got), text_lines(&want))
}

#[test]
fn grid_labels_match_the_c_references() {
    let mut failures = Vec::new();
    for case in grid_cases() {
        if GRID_LABELS_EXCLUDED.iter().any(|e| e.0 == case.name) {
            continue;
        }
        let (got, want) = labels_of(&case);
        if got != want {
            let diff = got
                .iter()
                .zip(&want)
                .find(|(g, w)| g != w)
                .map(|(g, w)| format!("got {g:?}, C gives {w:?}"))
                .unwrap_or_else(|| format!("{} labels, C gives {}", got.len(), want.len()));
            failures.push(format!("{}: {diff}", case.name));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn excluded_grid_labels_still_differ() {
    for &(name, reason) in GRID_LABELS_EXCLUDED {
        let case = grid_cases().into_iter().find(|c| c.name == name).unwrap();
        assert!(
            case.skip_text_compare,
            "{name} is excluded but C compares it"
        );
        let (got, want) = labels_of(&case);
        assert_ne!(
            got, want,
            "{name} now matches ({reason}); remove its exclusion"
        );
    }
}

/// A grid that fails part way leaves the Plot as it was, so a second grid
/// draws what it would have drawn first time.
#[test]
fn a_failing_backend_leaves_the_plot_unchanged() {
    let case = grid_cases().into_iter().find(|c| c.name == "car3").unwrap();
    let mut plot = testgrid_plot(&case);
    let before =
        crate::common::native_dump(&starlink_ast::AnyObject::Plot(Box::new(plot.clone()))).unwrap();
    let mut failing = FailingGrf {
        inner: LogGrf::new(Vec::new()),
        lines_left: 3,
    };
    let err = plot.draw_grid(&mut failing).unwrap_err();
    assert_eq!(err.code(), ErrorCode::Grfer);
    let after =
        crate::common::native_dump(&starlink_ast::AnyObject::Plot(Box::new(plot.clone()))).unwrap();
    assert_eq!(after, before);
    let mut log = LogGrf::new(Vec::new());
    plot.draw_grid(&mut log).unwrap();
    let got = String::from_utf8(log.finish().unwrap()).unwrap();
    let &(_, want, _) = logs::CASES.iter().find(|c| c.0 == "car3").unwrap();
    assert_eq!(got, want);
}

/// A second grid on the same Plot, or one after `used_values`, draws what
/// the first did.
#[test]
fn drawing_twice_gives_the_same_log() {
    let case = grid_cases()
        .into_iter()
        .find(|c| c.name == "aitoff")
        .unwrap();
    let mut plot = testgrid_plot(&case);
    plot.used_values(&mut LogGrf::new(Vec::new())).unwrap();
    let &(_, want, _) = logs::CASES.iter().find(|c| c.0 == "aitoff").unwrap();
    for _ in 0..2 {
        let mut log = LogGrf::new(Vec::new());
        plot.draw_grid(&mut log).unwrap();
        assert_eq!(String::from_utf8(log.finish().unwrap()).unwrap(), want);
    }
}

/// A 2-D Frame Plot with explicit tick values on axis 1, as a Native dump
/// carries them (a 3-D Plot sets them), read back.
fn plot_with_ticks(lines: &[&str]) -> Plot {
    let frame = BasicFrameBuilder::new(2).build().unwrap();
    let plot = Plot::new(&frame, [0.1, 0.1, 0.9, 0.9], [0.0, 0.0, 10.0, 10.0]).unwrap();
    let dump = crate::common::native_dump(&starlink_ast::AnyObject::Plot(Box::new(plot))).unwrap();
    let end = dump.rfind(" End Plot").unwrap();
    let mut text = dump[..end].to_string();
    for l in lines {
        text.push_str(&format!("   {l}\n"));
    }
    text.push_str(&dump[end..]);
    match starlink_ast::from_native_string(&text).unwrap() {
        starlink_ast::AnyObject::Plot(p) => *p,
        other => panic!("read a {}", other.class_name()),
    }
}

/// MinTick as a grid uses it is at least 1, as C's SetUsedMinTick makes
/// it, and explicit ticks with one major tick do not divide by zero.
#[test]
fn used_min_tick_is_at_least_one() {
    let mut plot = plot_with_ticks(&["NMjTk1 = 3", "MjTk1_1 = 2", "MjTk1_2 = 5", "MjTk1_3 = 8"]);
    let used = plot.used_values(&mut LogGrf::new(Vec::new())).unwrap();
    assert_eq!(used.min_tick[0], 1);
    let mut plot = plot_with_ticks(&[
        "NMjTk1 = 1",
        "MjTk1_1 = 5",
        "NMnTk1 = 2",
        "MnTk1_1 = 4",
        "MnTk1_2 = 6",
    ]);
    if let Ok(used) = plot.used_values(&mut LogGrf::new(Vec::new())) {
        assert_eq!(used.min_tick[0], 1);
    }
}
